\label{thm:main-AF}
Let $d\ge2$ and $\beta>\beta_c(d)$.  There exist $h_0=h_0(d,\beta)>0$, $c=c(d,\beta)>0$ such that for each $\lverth\rvert\le h_0$, 
\begin{equation}\label{eq:finite-gap-AF}
 \mu^{\mathrm{AF},\mathrm N+}_{B_n,\beta,h}\bigl[\sigma_0=+1\bigr]
 -\mu^{\mathrm{AF},\mathrm N-}_{B_n,\beta,h}\bigl[\sigma_0=+1\bigr]
 \ge c,
 \qquad \forall n\ge1.
\end{equation}

\label{prop:main-FM}
For $d\ge2$ and $\beta>\beta_c(d)$, there exist $h_0=h_0(d,\beta)>0,c=c(d,\beta)>0$ such that for each $|h|\leq h_0$,
\begin{equation}\label{eq:FM-main-gap}
\mu^{\mathrm{FM},+}_{B_n,\beta,h}\bigl[\sigma_0=+1\bigr]
-\mu^{\mathrm{FM},-}_{B_n,\beta,h}\bigl[\sigma_0=+1\bigr]
\ge c,
\qquad \forall n\ge1.
\end{equation}

\label{prop:zero-field-block}
Let $d\ge2$ and $\beta>\beta_c(d)$.  There exist $c_0=c_0(d,\beta) \in (0,\infty)$ and $q_0=q_0(d,\beta) \in (0,\infty)$ such that, for every integer $q\ge q_0$ and every FK boundary condition $\xi$ on $R_v$,
\begin{equation}\label{eq:zero-field-block}
 \phi^{\xi}_{R_v,\beta}\bigl[Q_v\text{ is bad}\bigr]\le e^{-c_0q}.
\end{equation}

\label{lem:reflection-positivity}
For every $i,b$ as above, $\widetilde{\mathbb P}_{L,\beta,h}$ is reflection
positive with respect to $\widetilde\vartheta_{i,b}$.

\label{lem:zero-field-all-bad}
Recall $c_0$ and $q_0$ from Proposition~\ref{prop:zero-field-block}.  Let $c_1:=c_0/4^d$. Then, for every $r\in\{0,1\}^d$,
\begin{equation}\label{eq:zero-field-all-bad}
 \mathbb P_{L,\beta,0}\left[Q_v\text{ is bad for every }v\in\mathcal A_r\right]
 \le e^{-c_1qM}, \qquad \forall q\geq q_0, L=q 2^{k+1} \text{ with }k\geq 2. 
\end{equation}

\label{prop:uniform-bad-block}
Recall $q_0$ and $c_1$ from Lemma \ref{lem:zero-field-all-bad}. For every odd $q\ge q_0$, set
\begin{equation}\label{eq:h0-choice}
 h_q:=\frac{c_1q}{4(2q)^d},\qquad
 r_q:=\exp\left[-\frac{c_1q}{2^{d+1}}\right].
\end{equation}
Then, for every $\lverth\rvert\le h_q$ and every
$S\subset\mathbb T_{L/q}$,
\begin{equation}\label{eq:uniform-bad-block}
 \mathbb P_{L,\beta,h}\left[Q_v\text{ is bad for every }v\in S\right]
 \le r_q^{\lvertS\rvert},
\end{equation}
uniformly over $L=q2^{k+1}$ with integer $k\ge2$.  In particular,
$r_q\downarrow0$ as $q\to\infty$ through odd integers.

\label{lem:good-geometry}
Let $d\ge2$ and $\mu$ be a probability measure on $\{0,1\}^{\mathbb Z^d}$.  Call a vertex \emph{open} when $\eta_v=1$ and \emph{closed} when $\eta_v=0$.  Suppose that, for some $r>0$,
\begin{equation}\label{eq:abstract-bad-bound}
 \mu\bigl[\eta_v=0\text{ for every }v\in A\bigr]\le r^{\lvertA\rvert}, \qquad \forall A\Subset\mathbb Z^d.
\end{equation}
Set $\kappa_d=(3^d-1)^2$.
If $r<\kappa_d^{-1}$, then the open vertices have,
$\mu$-almost surely, a unique infinite nearest-neighbor component
$\mathcal C_\infty$.  Moreover, for every $v\in\mathbb Z^d$,
\begin{equation}\label{eq:good-density}
 \mu\bigl[v\notin\mathcal C_\infty\bigr]
 \le r+\frac{\kappa_dr}{(1-\kappa_dr)^2}
 =:\delta_d(r).
\end{equation}
In particular, $\delta_d(r)\to0$ as $r\downarrow0$.

\label{lem:tail-sign}
For each $s\in \{-1,+1\}$,  $A_s$ is a tail event. Furthermore,
\begin{equation}\label{eq:sign-half}
 \mathbb P_{\beta,h}[A_+]=\mathbb P_{\beta,h}[A_-]=1/2.
\end{equation}

\label{lem:crossing-observable}
The function $f_q$ is increasing in $\sigma_{Q_0}$. For every sufficiently large odd $q$,
\begin{equation}\label{eq:crossing-bounds}
 \langle f_q\rangle_{\mu_h^+}\ge1-2\delta_q,
 \quad \forall |h|\le h_q,
 \qquad
 \langle f_q\rangle_{\mu_0^-}\le\epsilon_q,
\end{equation}
where $\epsilon_q\to0$ as $q\to\infty$.

\label{prop:continuity}
	Let $d\ge2$ and $\beta>\beta_c(d)$. Then
	\begin{equation}\label{eq:local-continuity}
		\mu^{\mathrm{FM},\pm}_{\beta,h}\Rightarrow\mu^{\mathrm{FM},\pm}_{\beta,0}, \ \mu^{\mathrm{AF},\mathrm N\pm}_{\beta,h}\Rightarrow\mu^{\mathrm{AF},\mathrm N\pm}_{\beta,0}
		\qquad\text{as }h\to0,
	\end{equation}
where $\Rightarrow$ denotes weak convergence.
